void test() {
    MockInvokersSelector selector = new MockInvokersSelector(URL.valueOf(""));
    // Data preparation
    Invoker<DemoService> invoker1 = Mockito.mock(Invoker.class);
    Invoker<DemoService> invoker2 = Mockito.mock(Invoker.class);
