    reportService.reportConsumptionStatus(reportService.createConsumptionReport(consumerURL.getServiceInterface(), consumerURL.getVersion(), consumerURL.getGroup(), "status"));
    // 3. reportMigrationStepStatus
    reportService.reportMigrationStepStatus(reportService.createMigrationStepReport(consumerURL.getServiceInterface(), consumerURL.getVersion(), consumerURL.getGroup(), "FORCE_INTERFACE", "FORCE_APPLICATION", "true"));
    MockFrameworkStatusReporter statusReporter = (MockFrameworkStatusReporter) applicationModel.getExtension(FrameworkStatusReporter.class, "mock");
