    Assertions.assertEquals("APPLICATION_FIRST", captor_event.getValue().getStep().toString());
    Mockito.verify(handler2, Mockito.times(2)).doMigrate(captor_event.capture());
    Assertions.assertEquals("APPLICATION_FIRST", captor_event.getValue().getStep().toString());
}

